    val n = readLine()!!.toLong()
    var min = 10000000000L
    var i = 1L
    while (i * i * i <= n) {
        if (n % i == 0L) {
            var j = i
            while (j * j <= n / i) {
                if (n % j == 0L) {
                    val k = n / (i * j)
                    val a = i + 1
                    val b = j + 2
                    val c = k + 2
